class Solution {
    static class Node {
        int cnt = 0;
        Node[] next = new Node[2];
    }
    Node root = new Node();
    void insert(int val) {
        Node curr = root;
        for (int i = 20; i >= 0; i--) {
            int b = (val >> i) & 1;
            if (curr.next[b] == null) curr.next[b] = new Node();
            curr = curr.next[b];
            curr.cnt++;
        }
    }
    void remove(int val) {
        Node curr = root;
        for (int i = 20; i >= 0; i--) {
            int b = (val >> i) & 1;
            curr = curr.next[b];
            curr.cnt--;
        }
    }
    int query(int val) {
        Node curr = root;
        int res = 0;
        for (int i = 20; i >= 0; i--) {
            int b = (val >> i) & 1;
            int want = 1 - b;
            if (curr.next[want] != null && curr.next[want].cnt > 0) {
                res |= (1 << i);
                curr = curr.next[want];
            } else if (curr.next[b] != null) {
                curr = curr.next[b];
            } else break;
        }
        return res;
    }
    public int maximumStrongPairXor(int[] nums) {
        Arrays.sort(nums);
        int l = 0, ans = 0;
        for (int r = 0; r < nums.length; r++) {
            insert(nums[r]);
            while (nums[r] > 2 * nums[l]) {
                remove(nums[l]);
                l++;
            }
            ans = Math.max(ans, query(nums[r]));
        }
        return ans;
    }
}

